import { test } from "vitest";
import assert from "node:assert/strict";
import Database from "better-sqlite3";
import { PullRequestReadyStore } from "./readyStore.js";
import { PullRequestReadyCoordinator } from "./readyCoordinator.js";
import { PullRequestError, type PullRequestObservation } from "./contract.js";

const head = "a".repeat(40);
const base = "b".repeat(40);
const repository = { provider: "other", instanceId: "fixture", nativeId: "repo" };
const draft: PullRequestObservation = { repository, nativeId: "pr-1",
  head: { repository, ref: "refs/heads/work", revision: head },
  base: { repository, ref: "refs/heads/main", revision: base },
  state: "open", draft: true, mergeable: true, mergeStrategy: "fast-forward-only",
  requiredChecks: [], requiredApprovals: 0, reviews: [], discussionCount: 0,
  providerRevision: "revision-1" };

test("owner-authorized readiness persists identity, reconciles a lost response, and never redispatches", async () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_ready_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, authority_id TEXT, state TEXT, recorded_at TEXT,
    updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const effects = new PullRequestReadyStore(sqlite);
    let observed = draft;
    let writes = 0;
    const coordinator = new PullRequestReadyCoordinator({ effects,
      verifyAuthority: async () => {}, now: () => "2026-10-14T00:00:00Z", effectId: () => "effect-1",
      adapter: { read: async () => observed, markReady: async () => {
        assert.equal(effects.get("effect-1")?.state, "pending");
        writes++;
        observed = { ...draft, draft: false };
        throw new Error("lost response");
      } } });
    const candidate = { bindingId: "pr", bindingRevision: 1, repository, nativePrId: "pr-1",
      headRevision: head, baseRef: "refs/heads/main", baseRevision: base, authorityId: "owner-policy-1" };
    assert.equal((await coordinator.markReady(candidate)).state, "confirmed");
    assert.equal((await coordinator.markReady(candidate)).state, "confirmed");
    assert.equal(writes, 1);
  } finally { sqlite.close(); }
});

test("uncertain readiness stays unknown and does not retry the provider write", async () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_ready_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, authority_id TEXT, state TEXT, recorded_at TEXT,
    updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const effects = new PullRequestReadyStore(sqlite);
    let writes = 0;
    const coordinator = new PullRequestReadyCoordinator({ effects,
      verifyAuthority: async () => {}, now: () => "2026-10-14T00:00:00Z", effectId: () => "effect-1",
      adapter: { read: async () => draft, markReady: async () => { writes++; throw new Error("timeout"); } } });
    const candidate = { bindingId: "pr", bindingRevision: 1, repository, nativePrId: "pr-1",
      headRevision: head, baseRef: "refs/heads/main", baseRevision: base, authorityId: "owner-policy-1" };
    await assert.rejects(coordinator.markReady(candidate), (error: unknown) =>
      error instanceof PullRequestError && error.code === "ready_outcome_unknown");
    await assert.rejects(coordinator.markReady(candidate), (error: unknown) =>
      error instanceof PullRequestError && error.code === "ready_outcome_unknown");
    assert.equal(writes, 1);
    assert.equal(effects.get("effect-1")?.state, "unknown");
  } finally { sqlite.close(); }
});

test("a failed readiness preflight remains retryable without claiming an unknown write", async () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_ready_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, authority_id TEXT, state TEXT, recorded_at TEXT,
    updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const effects = new PullRequestReadyStore(sqlite);
    let observed: PullRequestObservation | null = null;
    let writes = 0;
    const coordinator = new PullRequestReadyCoordinator({ effects,
      verifyAuthority: async () => {}, now: () => "2026-10-14T00:00:00Z", effectId: () => "effect-1",
      adapter: { read: async () => observed, markReady: async () => {
        writes++;
        observed = { ...draft, draft: false };
        return observed;
      } } });
    const candidate = { bindingId: "pr", bindingRevision: 1, repository, nativePrId: "pr-1",
      headRevision: head, baseRef: "refs/heads/main", baseRevision: base, authorityId: "owner-policy-1" };
    await assert.rejects(coordinator.markReady(candidate), (error: unknown) =>
      error instanceof PullRequestError && error.code === "pr_missing");
    assert.equal(effects.get("effect-1")?.state, "preflight");
    assert.equal(writes, 0);
    observed = draft;
    assert.equal((await coordinator.markReady(candidate)).state, "confirmed");
    assert.equal(writes, 1);
  } finally { sqlite.close(); }
});

test("an invalid post-write observation leaves the readiness effect unknown", async () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_ready_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, authority_id TEXT, state TEXT, recorded_at TEXT,
    updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const effects = new PullRequestReadyStore(sqlite);
    let observed = draft;
    const coordinator = new PullRequestReadyCoordinator({ effects,
      verifyAuthority: async () => {}, now: () => "2026-10-14T00:00:00Z", effectId: () => "effect-1",
      adapter: { read: async () => observed, markReady: async () => {
        observed = { ...draft, draft: false, head: { ...draft.head, revision: "invalid" } };
        throw new Error("lost response");
      } } });
    await assert.rejects(coordinator.markReady({ bindingId: "pr", bindingRevision: 1, repository,
      nativePrId: "pr-1", headRevision: head, baseRef: "refs/heads/main", baseRevision: base,
      authorityId: "owner-policy-1" }), (error: unknown) =>
      error instanceof PullRequestError && error.code === "ready_outcome_unknown");
    assert.equal(effects.get("effect-1")?.state, "unknown");
  } finally { sqlite.close(); }
});

